/**
 * Builds assets/js/example-dialogues-ko.js
 * Run: node scripts/build-example-dialogues-ko.cjs
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'assets/js/example-dialogues-ko.js');
const source = require('./example-dialogues-ko-data.cjs');
const dialogues = source.dialogues || source;
const expectedCount = source.expectedCount || 6;

const header = `// Korean example dialogues for Cupid free-talk voice anchors
// Generated by scripts/build-example-dialogues-ko.cjs - do not hand-edit
const EXAMPLE_DIALOGUES_KO = `;
const footer = `;
window.EXAMPLE_DIALOGUES_KO = EXAMPLE_DIALOGUES_KO;
`;

fs.writeFileSync(OUT, header + JSON.stringify(dialogues, null, 2) + footer, 'utf8');

const ids = Object.keys(dialogues);
const bad = ids.filter((id) => !Array.isArray(dialogues[id]) || dialogues[id].length !== expectedCount);
if (bad.length) {
    console.error('Expected ' + expectedCount + ' dialogues each. Bad: ' + bad.map((id) => id + '=' + (dialogues[id] || []).length).join(', '));
    process.exit(1);
}
console.log('Wrote ' + OUT + ' - ' + ids.length + ' characters, ' + ids.reduce((sum, id) => sum + dialogues[id].length, 0) + ' dialogues');
